local function Clean(Value)
	if type(Value) ~= "string" then
		return nil
	end
	Value = string.gsub(Value, "%s+", "")
	if Value == "" then
		return nil
	end
	return Value
end

local function DeviceId()
	if type(gethwid) == "function" then
		local Ok, Value = pcall(gethwid)
		local Id = Ok and Clean(Value)
		if Id then
			return Id
		end
	end
	local Ok, Value = pcall(function()
		return game:GetService("RbxAnalyticsService"):GetClientId()
	end)
	return (Ok and Clean(Value)) or ""
end

local function XorText(Text, Key)
	local Out = {}
	local Width = #Key
	for Index = 1, #Text do
		Out[Index] = string.char(bit32.bxor(string.byte(Text, Index), string.byte(Key, ((Index - 1) % Width) + 1)))
	end
	return table.concat(Out)
end

local function Unhex(Text)
	if #Text % 2 ~= 0 then
		return nil
	end
	local Out = {}
	for Index = 1, #Text, 2 do
		local Byte = tonumber(string.sub(Text, Index, Index + 1), 16)
		if not Byte then
			return nil
		end
		Out[#Out + 1] = string.char(Byte)
	end
	return table.concat(Out)
end

local function Decode(Data)
	local Map = {}
	local Alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	for Index = 1, #Alphabet do
		Map[string.sub(Alphabet, Index, Index)] = Index - 1
	end
	local Out = {}
	local Spot = 1
	while Spot <= #Data do
		local A = Map[string.sub(Data, Spot, Spot)] or 0
		local B = Map[string.sub(Data, Spot + 1, Spot + 1)] or 0
		local C = Map[string.sub(Data, Spot + 2, Spot + 2)]
		local D = Map[string.sub(Data, Spot + 3, Spot + 3)]
		local Value = A * 262144 + B * 4096 + (C or 0) * 64 + (D or 0)
		Out[#Out + 1] = string.char(math.floor(Value / 65536) % 256)
		if C then
			Out[#Out + 1] = string.char(math.floor(Value / 256) % 256)
		end
		if D then
			Out[#Out + 1] = string.char(Value % 256)
		end
		Spot = Spot + 4
	end
	return table.concat(Out)
end

local function Encode(Data)
	local Alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	local Out = {}
	local Index = 1
	while Index <= #Data do
		local A = string.byte(Data, Index)
		local B = string.byte(Data, Index + 1)
		local C = string.byte(Data, Index + 2)
		local Triple = A * 65536 + (B or 0) * 256 + (C or 0)
		local First = math.floor(Triple / 262144) % 64
		local Second = math.floor(Triple / 4096) % 64
		local Third = math.floor(Triple / 64) % 64
		local Fourth = Triple % 64
		Out[#Out + 1] = string.sub(Alphabet, First + 1, First + 1)
		Out[#Out + 1] = string.sub(Alphabet, Second + 1, Second + 1)
		Out[#Out + 1] = B and string.sub(Alphabet, Third + 1, Third + 1) or "="
		Out[#Out + 1] = C and string.sub(Alphabet, Fourth + 1, Fourth + 1) or "="
		Index = Index + 3
	end
	return table.concat(Out)
end

local function Open(Blob)
	return XorText(Decode(Blob), Secret)
end

local function Seal(Text)
	return Encode(XorText(Text, Secret))
end

local function KeyText()
	local Value = getgenv and getgenv().YaufrjsKey
	local Typed = Clean(Value)
	if Typed then
		return string.upper(Typed)
	end
	if readfile and isfile and isfile("yaufrjs/key.txt") then
		local Ok, Text = pcall(readfile, "yaufrjs/key.txt")
		local Saved = Ok and Clean(Text)
		if Saved then
			return string.upper(Saved)
		end
	end
	return ""
end

local LicenseUrl = "http://127.0.0.1:3010/api/verify"

local function ReasonText(Reason)
	if Reason == "invalid_key" then
		return "That key is not in the list"
	end
	if Reason == "disabled" then
		return "This key is turned off"
	end
	if Reason == "expired" then
		return "This key has expired"
	end
	if Reason == "hwid_mismatch" then
		return "This key is already used on another device"
	end
	if Reason == "missing_key" then
		return "Enter a key"
	end
	if Reason == "missing_hwid" then
		return "This executor did not give a device id"
	end
	if Reason == "rate" then
		return "Wait a moment and try again"
	end
	return "Activation server is not running"
end

local function AskServer(Key, Id)
	local Request = request or http_request or (syn and syn.request)
	if not Request then
		return false, "This executor cannot reach the activation server"
	end
	local Http = game:GetService("HttpService")
	local Ok, Res = pcall(Request, {
		Url = LicenseUrl,
		Method = "POST",
		Headers = { ["Content-Type"] = "application/json" },
		Body = Http:JSONEncode({ key = Key, hwid = Id }),
	})
	if not Ok or type(Res) ~= "table" or type(Res.Body) ~= "string" then
		return false, ReasonText("down")
	end
	local Parsed = {}
	pcall(function()
		Parsed = Http:JSONDecode(Res.Body)
	end)
	if tonumber(Res.StatusCode) == 200 and type(Parsed) == "table" and Parsed.ok == true then
		return true, "Activated"
	end
	return false, ReasonText(type(Parsed) == "table" and Parsed.reason or nil)
end

local function SaveKey(Key)
	pcall(function()
		if makefolder then
			makefolder("yaufrjs")
		end
	end)
	if writefile then
		pcall(writefile, "yaufrjs/key.txt", Key)
	end
end

