local function Licensed()
	local Id = DeviceId()
	if Id == "" then
		print("[yaufrjs] this executor did not give a device id")
		return false
	end
	local Saved = KeyText()
	local Failed = ""
	if Saved ~= "" then
		local Ok, Message = AskServer(Saved, Id)
		if Ok then
			return true
		end
		Failed = Message
	end
	return PromptKey(Id, Failed)
end

local function Halt()
	local Gen = getgenv and getgenv()
	if type(Gen) == "table" then
		local Live = Gen.YaufrjsFruitSettings
		if type(Live) == "table" then
			Live.PvpGo = false
			Live.Collect = false
			Live.GachaOpen = false
			Live.CollectChest = false
			Live.CollectBerry = false
		end
		for _, Name in ipairs({ "YaufrjsBerryStop", "YaufrjsFruitStop", "YaufrjsPvpStop" }) do
			local Stop = Gen[Name]
			Gen[Name] = nil
			if type(Stop) == "function" then
				pcall(Stop)
			end
		end
		Gen.YaufrjsFruitToken = (Gen.YaufrjsFruitToken or 0) + 1
		Gen.YaufrjsBerryToken = (Gen.YaufrjsBerryToken or 0) + 1
		Gen.YaufrjsFlyingTo = nil
		Gen.YaufrjsBootAt = nil
		Gen.YaufrjsHold = true
		local Watch = Gen.YaufrjsWorldWatch
		if typeof(Watch) == "RBXScriptConnection" then
			pcall(function()
				Watch:Disconnect()
			end)
		end
		Gen.YaufrjsWorldWatch = nil
	end
	pcall(function()
		game:GetService("RunService"):UnbindFromRenderStep("YaufrjsPvpPin")
	end)
	local Hosts = {}
	if type(gethui) == "function" then
		local Ok, Host = pcall(gethui)
		if Ok and Host then
			Hosts[#Hosts + 1] = Host
		end
	end
	local CoreOk, Core = pcall(function()
		return game:GetService("CoreGui")
	end)
	if CoreOk and Core then
		Hosts[#Hosts + 1] = Core
	end
	local Player = game:GetService("Players").LocalPlayer
	local PlayerGui = Player and Player:FindFirstChild("PlayerGui")
	if PlayerGui then
		Hosts[#Hosts + 1] = PlayerGui
	end
	for _, Host in ipairs(Hosts) do
		for _, Child in ipairs(Host:GetChildren()) do
			if Child:IsA("ScreenGui") and (Child.Name == "yaufrjs-fruits" or Child.Name == "Fluent" or Child.Name == "FluentUI" or Child.Name == "yaufrjs-activate") then
				pcall(function()
					Child:Destroy()
				end)
			end
		end
	end
end

