local function Token()
	local Value = getgenv and getgenv().YaufrjsToken
	local Typed = Clean(Value)
	if Typed then
		return Typed
	end
	if readfile and isfile and isfile("yaufrjs/github.txt") then
		local Ok, Text = pcall(readfile, "yaufrjs/github.txt")
		local Saved = Ok and Clean(Text)
		if Saved then
			return Saved
		end
	end
	return ""
end

local function Fetch(Name)
	local Key = Token()
	if Key == "" then
		return nil
	end
	local Request = request or http_request or (syn and syn.request)
	if not Request then
		return nil
	end
	local Ok, Res = pcall(Request, {
		Url = Repo .. "/src/" .. Name .. ".lua?ref=main",
		Method = "GET",
		Headers = {
			Authorization = "Bearer " .. Key,
			Accept = "application/vnd.github.raw",
			["User-Agent"] = "yaufrjs",
		},
	})
	if not Ok or type(Res) ~= "table" or type(Res.Body) ~= "string" or Res.Body == "" then
		return nil
	end
	if Res.StatusCode and Res.StatusCode ~= 200 then
		return nil
	end
	return Res.Body
end

